node - <<'NODE'
const url = 'ws://192.168.0.16/rpc';
const src = 'lcl_button_probe';
if (typeof WebSocket === 'undefined') {
  console.error('NO_GLOBAL_WEBSOCKET');
  process.exit(2);
}
const ws = new WebSocket(url);
let done = false;
const finish = (reason) => {
  if (done) return;
  done = true;
  console.log('=== LISTENER_END ===', reason);
  try { ws.close(); } catch {}
  setTimeout(() => process.exit(0), 250);
};
const timer = setTimeout(() => finish('120s timeout'), 120000);
ws.onopen = () => {
  console.log('=== WS_OPEN ===');
  ws.send(JSON.stringify({id: 1, src, method: 'Shelly.GetDeviceInfo'}));
};
ws.onmessage = (event) => {
  const text = typeof event.data === 'string' ? event.data : String(event.data);
  console.log(new Date().toISOString(), text);
};
ws.onerror = (event) => {
  console.error('=== WS_ERROR ===', event?.message || event?.type || String(event));
};
ws.onclose = (event) => {
  clearTimeout(timer);
  if (!done) {
    done = true;
    console.log('=== WS_CLOSE ===', event.code, event.reason || '');
    process.exit(0);
  }
};
NODE
